101	// Loading helper
102	// ---------------------------------------------------------------------------
103	
104	/**
105	 * Render a loading spinner into `el`.
106	 *
107	 * @param {HTMLElement} el
108	 * @param {string} [label]
109	 */
110	function showLoading(el, label = 'Loading…') {
111	    el.innerHTML = '';
112	    const wrapper = document.createElement('div');
113	    wrapper.className = 'loading-indicator';
114	    wrapper.setAttribute('aria-live', 'polite');
115	
116	    const spinner = document.createElement('span');
117	    spinner.className = 'spinner';
118	    spinner.setAttribute('aria-hidden', 'true');
119	    wrapper.appendChild(spinner);
120	
121	    const labelEl = document.createElement('span');
122	    labelEl.textContent = label;
123	    wrapper.appendChild(labelEl);
124	
125	    el.appendChild(wrapper);
126	}
127	
128	// ---------------------------------------------------------------------------
129	// Setup helper
130	// ---------------------------------------------------------------------------
131	
132	/**
133	 * Run workspace setup and show appropriate toast notification.
134	 *
135	 * @param {string} projectId
136	 * @param {string} workspaceId
137	 * @param {string} successMessage - Toast message shown when all repos succeed.
138	 * @returns {Promise<Object>} The setup result from the API.
139	 * @throws {Error} Re-throws API errors for the caller to handle.
140	 */
141	async function runSetup(projectId, workspaceId, successMessage) {
142	    const result = await api.workspaces.setup(projectId, workspaceId);
143	    const failures = (result && result.results || []).filter((r) => !r.success);
144	    if (failures.length > 0) {
145	        const names = failures.map((f) => f.repositoryId).join(', ');
146	        showToast(`Setup complete with errors. Failed to clone: ${names}`, 'warning', 8000);
147	    } else {
148	        showToast(successMessage, 'success');
149	    }
150	    return result;
151	}
152	
153	// ---------------------------------------------------------------------------
154	// Status table helpers
155	// ---------------------------------------------------------------------------
156	
157	/**
158	 * Build the status `<tbody>` row for a single repository.
159	 *
160	 * The row uses `data-repo-id` on the badge container so the polling update
161	 * can locate and replace badge contents in-place.
162	 *
163	 * @param {string} repoId
164	 * @param {string} repoName
165	 * @param {Object|null} statusInfo - GitStatusInfo or null.
166	 * @param {string} projectId - Project ID, used by the "Open" button.
167	 * @param {string} wid - Workspace ID, used by the "Open" button.
168	 * @returns {HTMLTableRowElement}
169	 */
170	function buildRepoStatusRow(repoId, repoName, statusInfo, projectId, wid) {
171	    const tr = document.createElement('tr');
172	    tr.dataset.repoId = repoId;
173	
174	    // Repository name / ID
175	    const nameCell = document.createElement('td');
176	    nameCell.className = 'repo-name-cell';
177	    const nameEl = document.createElement('span');
178	    nameEl.className = 'repo-name';
179	    nameEl.textContent = repoName;
180	    if (repoName !== repoId) {
181	        const idHint = document.createElement('span');
182	        idHint.className = 'text-muted repo-id-hint';
183	        idHint.textContent = ` (${repoId})`;
184	        nameEl.appendChild(idHint);
185	    }
186	    nameCell.appendChild(nameEl);
187	    tr.appendChild(nameCell);
188	
189	    // Branch name
190	    const branchCell = document.createElement('td');
191	    branchCell.className = 'repo-branch-cell';
192	    branchCell.textContent = (statusInfo && statusInfo.currentBranch)
193	        ? statusInfo.currentBranch
194	        : '—';
195	    tr.appendChild(branchCell);
196	
197	    // Status badge cell (index 2 — must stay at this position)
198	    const badgeCell = document.createElement('td');
199	    badgeCell.className = 'repo-badge-cell';
200	
201	    const badgeWrapper = document.createElement('div');
202	    badgeWrapper.dataset.repoId = repoId;
203	    badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
204	    badgeCell.appendChild(badgeWrapper);
205	    tr.appendChild(badgeCell);
206	
207	    // Actions cell (index 3) — "Open" button for GitHub Desktop
208	    const actionsCell = document.createElement('td');
209	    actionsCell.className = 'repo-actions-cell';
210	
211	    const openBtn = document.createElement('button');
212	    openBtn.type      = 'button';
213	    openBtn.className = 'btn btn-secondary btn-sm';
214	    openBtn.textContent = 'Open';
215	    openBtn.title = 'Open this repository in GitHub Desktop.';
216	
217	    openBtn.addEventListener('click', async () => {
218	        openBtn.disabled    = true;
219	        openBtn.textContent = 'Opening…';
220	        try {
221	            await api.workspaces.openGithubDesktop(projectId, wid, repoId);
222	        } catch (err) {
223	            showToast(err.message || 'Failed to open GitHub Desktop.', 'error');
224	        } finally {
225	            openBtn.disabled    = false;
226	            openBtn.textContent = 'Open';
227	        }
228	    });
229	
230	    actionsCell.appendChild(openBtn);
231	    tr.appendChild(actionsCell);
232	
233	    return tr;
234	}
235	
236	/**
237	 * Update an existing status table in-place by replacing badge contents and
238	 * branch text for each repository whose status has changed.
239	 *
240	 * Rows are located via `[data-repo-id]` on both the `<tr>` and the badge
241	 * wrapper `<div>` inside it. No full re-render of the table is performed.
242	 *
243	 * @param {HTMLElement}           tableBody - The `<tbody>` to update.
244	 * @param {Record<string, Object|null>} statusMap - Keyed by repository ID.
245	 */
246	function updateStatusTable(tableBody, statusMap) {
247	    for (const [repoId, statusInfo] of Object.entries(statusMap)) {
248	        const row = tableBody.querySelector(`tr[data-repo-id="${CSS.escape(repoId)}"]`);
249	        if (!row) continue;

251	        // Update branch cell (second cell)
252	        const branchCell = row.cells[1];
253	        if (branchCell) {
254	            branchCell.textContent = (statusInfo && statusInfo.currentBranch)
255	                ? statusInfo.currentBranch
256	                : '—';
257	        }
258	
259	        // Update badge wrapper (third cell → div[data-repo-id])
260	        const badgeWrapper = row.querySelector(`div[data-repo-id="${CSS.escape(repoId)}"]`);
261	        if (badgeWrapper) {
262	            badgeWrapper.innerHTML = '';
263	            badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
264	        }
265	    }
266	}
267	
268	// ---------------------------------------------------------------------------
269	// Section builders
270	// ---------------------------------------------------------------------------
271	
272	/**
273	 * Build the rename workspace inline form and wire up its event handlers.
274	 *
275	 * @param {string} projectId
276	 * @param {{ id: string }} workspace
277	 * @param {HTMLButtonElement} renameBtn - The "Rename" button that toggles form visibility.
278	 * @returns {HTMLElement}
279	 */
280	function buildRenameForm(projectId, workspace, renameBtn) {
281	    const wrapper = document.createElement('div');
282	    wrapper.className = 'rename-workspace-form-wrapper card';
283	    wrapper.hidden = true;
284	
285	    const formTitle = document.createElement('h4');
286	    formTitle.className   = 'form-section-title';
287	    formTitle.textContent = 'Rename Workspace';
288	    wrapper.appendChild(formTitle);
289	
290	    const newIdField = createFormField('New Workspace ID', 'text', 'newWorkspaceId', {
291	        required:    true,
292	        placeholder: 'e.g. DEV or FEATURE',
293	        hint:        'Must be 2–10 uppercase letters (A-Z only).',
294	    });
295	    wrapper.appendChild(newIdField);
296	
297	    const newIdInput   = newIdField.querySelector('[name="newWorkspaceId"]');
298	    const newIdErrorEl = newIdField.querySelector('.field-error');
299	
300	    const formActions = document.createElement('div');
301	    formActions.className = 'form-actions';
302	
303	    const saveBtn = document.createElement('button');
304	    saveBtn.type      = 'button';
305	    saveBtn.className = 'btn btn-primary btn-sm';
306	    saveBtn.textContent = 'Save';
307	
308	    const cancelFormBtn = document.createElement('button');
309	    cancelFormBtn.type      = 'button';
310	    cancelFormBtn.className = 'btn btn-secondary btn-sm';
311	    cancelFormBtn.textContent = 'Cancel';
312	
313	    formActions.appendChild(saveBtn);
314	    formActions.appendChild(cancelFormBtn);
315	    wrapper.appendChild(formActions);
316	
317	    // Behaviour
318	    renameBtn.addEventListener('click', () => {
319	        wrapper.hidden = false;
320	        if (newIdInput) newIdInput.focus();
321	    });
322	
323	    cancelFormBtn.addEventListener('click', () => {
324	        wrapper.hidden = true;
325	        if (newIdInput) newIdInput.value = '';
326	        if (newIdErrorEl) newIdErrorEl.hidden = true;
327	    });
328	
329	    saveBtn.addEventListener('click', async () => {
330	        if (newIdErrorEl) newIdErrorEl.hidden = true;
331	        if (newIdInput) {
332	            newIdInput.classList.remove('error');
333	            newIdInput.removeAttribute('aria-invalid');
334	        }
335	
336	        if (!validateRequired(wrapper, ['newWorkspaceId'])) return;
337	
338	        const newId = newIdInput ? newIdInput.value.trim() : '';
339	
340	        if (!WORKSPACE_ID_PATTERN.test(newId)) {
341	            if (newIdErrorEl) {
342	                newIdErrorEl.textContent = 'Must be 2–10 uppercase letters (A-Z only).';
343	                newIdErrorEl.hidden      = false;
344	            }
345	            if (newIdInput) {
346	                newIdInput.classList.add('error');
347	                newIdInput.setAttribute('aria-invalid', 'true');
348	                newIdInput.focus();
349	            }
350	            return;
351	        }
352	
353	        try {
354	            await showConfirm(
355	                'Rename Workspace',
356	                `Rename workspace "${workspace.id}" to "${newId}"? The page will navigate to the new workspace URL.`,
357	            );
358	        } catch {
359	            return;
360	        }
361	
362	        saveBtn.disabled    = true;
363	        saveBtn.textContent = 'Saving…';
364	
365	        try {
366	            await api.workspaces.rename(projectId, workspace.id, newId);
367	            showToast(`Workspace renamed to "${newId}".`, 'success');
368	            const target = `#/projects/${encodeURIComponent(projectId)}/workspaces/${encodeURIComponent(newId)}`;
369	            if (_router) {
370	                _router.navigate(target);
371	            } else {
372	                location.hash = target;
