691	/**
692	 * Build a health alert section element from a workspace health report.
693	 * Returns `null` when the workspace is healthy (no issues to display).
694	 *
695	 * Fix-action buttons are wired via the `callbacks` argument so the
696	 * caller can inject async handlers that match the surrounding view's
697	 * closure state (project/workspace IDs, toast helper, etc.).
698	 *
699	 * @param {{ healthy: boolean, issues: Array<{ type: string, severity: string, message: string, fixAction: string, repositoryId?: string }> }|null} healthReport
700	 * @param {{ onRegenerate: function(): Promise<void>, onSetup: function(): Promise<void> }} callbacks
701	 * @returns {HTMLElement|null}
702	 */
703	function buildHealthAlertSection(healthReport, callbacks) {
704	    if (
705	        !healthReport ||
706	        healthReport.healthy ||
707	        !Array.isArray(healthReport.issues) ||
708	        healthReport.issues.length === 0
709	    ) {
710	        return null;
711	    }
712	
713	    const section = document.createElement('div');
714	    section.className = 'health-alert';
715	
716	    const title = document.createElement('div');
717	    title.className = 'health-alert-title';
718	    title.textContent = 'Workspace health issues detected';
719	    section.appendChild(title);
720	
721	    for (const issue of healthReport.issues) {
722	        const row = document.createElement('div');
723	        row.className = 'health-alert-issue';
724	
725	        const msg = document.createElement('span');
726	        msg.className = 'health-alert-issue__message';
727	        msg.textContent = issue.message;
728	        row.appendChild(msg);
729	
730	        if (issue.fixAction === 'regenerate-workspace-file') {
731	            const actionWrap = document.createElement('span');
732	            actionWrap.className = 'health-alert-issue__action';
733	
734	            const btn = document.createElement('button');
735	            btn.type = 'button';
736	            btn.className = 'btn btn-secondary btn-sm';
737	            btn.textContent = 'Regenerate File';
738	            btn.addEventListener('click', async () => {
739	                btn.disabled = true;
740	                btn.textContent = 'Regenerating\u2026';
741	                try {
742	                    await callbacks.onRegenerate();
743	                } finally {
744	                    btn.disabled = false;
745	                    btn.textContent = 'Regenerate File';
746	                }
747	            });
748	            actionWrap.appendChild(btn);
749	            row.appendChild(actionWrap);
750	        } else if (issue.fixAction === 'setup-workspace') {
751	            const actionWrap = document.createElement('span');
752	            actionWrap.className = 'health-alert-issue__action';
753	
754	            const btn = document.createElement('button');
755	            btn.type = 'button';
756	            btn.className = 'btn btn-secondary btn-sm';
757	            btn.textContent = 'Fix Setup';
758	            btn.addEventListener('click', async () => {
759	                btn.disabled = true;
760	                btn.textContent = 'Setting up\u2026';
761	                try {
762	                    await callbacks.onSetup();
763	                } finally {
764	                    btn.disabled = false;
765	                    btn.textContent = 'Fix Setup';
766	                }
767	            });
768	            actionWrap.appendChild(btn);
769	            row.appendChild(actionWrap);
770	        }
771	        // Issues with an unknown fixAction render the message row without a button.
772	
773	        section.appendChild(row);
774	    }
775	
776	    return section;
777	}
