783	/**
784	 * Render the workspace detail view.
785	 *
786	 * Fetches workspace metadata, project (for the repositories list), polling
787	 * configuration, and initial Git status in parallel. Then starts a polling
788	 * interval that updates badges in-place using the server-configured interval
789	 * (falls back to {@link DEFAULT_POLL_INTERVAL_MS} if the config fetch fails).
790	 *
791	 * @param {HTMLElement} container - The `#app` DOM element provided by the router.
792	 * @param {{ id: string, wid: string }} params - Route parameters.
793	 * @returns {function(): void} Cleanup function — clears the polling interval.
794	 *   The router stores and calls this before rendering the next view.
795	 */
796	export function renderWorkspaceDetail(container, params) {
797	    const projectId = params.id;
798	    const wid       = params.wid;
799	
800	    let countdownInterval = null;

801	
802	    // Return the cleanup function immediately so the router can register it
803	    // even if the async bootstrap hasn't resolved yet.
804	    const cleanup = () => {
805	        if (countdownInterval !== null) {
806	            clearInterval(countdownInterval);
807	            countdownInterval = null;
808	        }
809	    };
810	
811	    // Show loading state immediately.
812	    showLoading(container, 'Loading workspace…');
813	
814	    // Kick off parallel data fetch.
815	    Promise.all([
816	        api.workspaces.get(projectId, wid),
817	        api.projects.get(projectId),
818	        api.status.refresh(projectId, wid),
819	        api.config.polling.get().catch(() => null),
820	        api.workspaces.health(projectId, wid).catch(() => null),
821	    ]).then((results) => {
822	        const [rawWorkspace, rawProject, statusMap, pollingConfig, healthReport] = results;
823	        // Guard: if the container was cleared by navigation before we resolved,
824	        // do nothing and let the cleanup function handle the interval.
825	        if (!container.isConnected) return;
826	
827	        const workspace = normaliseWorkspace(rawWorkspace);
828	        const project   = normaliseProject(rawProject);
829	
830	        // Build repo list: [{ repoId, repoName }, …]
831	        const repos = project.repositories.map((r) => ({
832	            repoId:   extractRepoId(r),
833	            repoName: extractRepoName(r),
834	        })).filter((r) => r.repoId !== '');
835	
836	        // Render the view.
837	        container.innerHTML = '';
838	
839	        const isStable = wid === STABLE_WS_ID;
840	
841	        // Resolve the effective poll interval from server config, with fallback.
842	        const pollIntervalMs = (
843	            pollingConfig &&
844	            typeof pollingConfig.gitPollingIntervalSeconds === 'number' &&
845	            Number.isFinite(pollingConfig.gitPollingIntervalSeconds) &&
846	            pollingConfig.gitPollingIntervalSeconds > 0
847	        )
848	            ? pollingConfig.gitPollingIntervalSeconds * 1000
849	            : DEFAULT_POLL_INTERVAL_MS;
850	
851	        // Build status table first to obtain tbody reference for helpers.
852	        const { section: statusSection, tbody } = buildStatusTableSection(repos, statusMap || {}, projectId, wid);
853	
854	        // -------------------------------------------------------------------
855	        // Refresh helpers (referenced by toolbar, polling, and setup)
856	        // -------------------------------------------------------------------
857	
858	        let remainingSeconds = pollIntervalMs / 1000;
859	        let refreshInProgress = false;
860	
861	        // Retry row reference — kept so polling can update/hide it.
862	        let retryRow = null;
863	        let retryHint = null;
864	
865	        // Toolbar elements — built now, wired after helpers are defined.
866	        const toolbar = buildRefreshToolbar();
867	        const progressBar = toolbar.querySelector('.refresh-progress-bar');
868	        const refreshNowBtn = toolbar.querySelector('.refresh-now-btn');
869	
870	        // Health section container — always in DOM between header and toolbar;
871	        // empty when the workspace is healthy.
872	        const healthContainerEl = document.createElement('div');
873	
874	        // Latest health report — kept in sync by renderHealthSection so that
875	        // updateMissingReposRow can exclude repos already covered by health alerts.
876	        let currentHealthReport = healthReport;
877	
878	        /**
879	         * Re-evaluate missing repos after a status update and hide/update
880	         * the retry row accordingly.
881	         *
882	         * Repos flagged by a `repository-not-cloned` health alert (fixAction:
883	         * `setup-workspace`) are excluded from the missing-repos count here
884	         * because the health alert already surfaces a fix button for them.
885	         * This row is therefore reserved for the transient polling-lag case
886	         * where `.git/` is present but status data has not arrived yet.
887	         */
888	        function updateMissingReposRow(freshStatusMap) {
889	            const notClonedIds = new Set(
890	                (currentHealthReport && Array.isArray(currentHealthReport.issues)
891	                    ? currentHealthReport.issues : [])
892	                    .filter((i) => i.fixAction === 'setup-workspace' && i.repositoryId)
893	                    .map((i) => i.repositoryId),
894	            );
895	            const currentMissing = repos.filter(
896	                (r) => !freshStatusMap[r.repoId] && !notClonedIds.has(r.repoId),
897	            );
898	            if (currentMissing.length === 0) {
899	                if (retryRow) {
900	                    retryRow.remove();
901	                    retryRow = null;
902	                    retryHint = null;
903	                }
904	            } else if (retryHint) {
905	                retryHint.textContent = `${currentMissing.length} ${currentMissing.length === 1 ? 'repository has' : 'repositories have'} no data \u2014 clone may have failed.`;
906	            }
907	        }
908	
909	        /**
910	         * Rebuild the health alert container from the given health report.
911	         * Updates `currentHealthReport` first so subsequent
912	         * `updateMissingReposRow` calls reflect the latest health state.
913	         *
914	         * @param {{ healthy: boolean, issues: Array }|null} report
915	         */
916	        function renderHealthSection(report) {
917	            currentHealthReport = report;
918	            healthContainerEl.innerHTML = '';
919	            const el = buildHealthAlertSection(report, {
920	                onRegenerate: async () => {
921	                    try {
922	                        await api.workspaces.regenerateFile(projectId, wid);
923	                        showToast('Workspace file regenerated.', 'success');
924	                        await fetchAndRenderHealth();
925	                    } catch (err) {
926	                        showToast(err.message || 'Failed to regenerate workspace file.', 'error');
927	                    }
928	                },
929	                onSetup: async () => {
930	                    try {
931	                        await runSetup(projectId, wid, 'Workspace setup complete.');
932	                        doRefresh();
933	                        await fetchAndRenderHealth();
934	                    } catch (err) {
935	                        showToast(err.message || 'Failed to set up workspace.', 'error');
936	                    }
937	                },
938	            });
939	            if (el) {
940	                healthContainerEl.appendChild(el);
941	            }
942	        }
943	
944	        /**
945	         * Fetch the latest health report from the API and re-render the
946	         * health alert section in-place. Silently ignores network errors.
947	         */
948	        async function fetchAndRenderHealth() {
949	            try {
950	                const fresh = await api.workspaces.health(projectId, wid);

 951	                if (container.isConnected) {
 952	                    renderHealthSection(fresh);
 953	                }
 954	            } catch {
 955	                // Silently ignore health fetch errors — stale UI remains.
 956	            }
 957	        }
 958	
 959	        /**
 960	         * Automatic poll — uses cached status endpoint.
 961	         */
 962	        async function doPoll() {
 963	            if (refreshInProgress) return;
 964	            refreshInProgress = true;
 965	            try {
 966	                const [fresh, freshHealth] = await Promise.all([
 967	                    api.status.get(projectId, wid),
 968	                    api.workspaces.health(projectId, wid).catch(() => null),
 969	                ]);
 970	                if (container.isConnected) {
 971	                    renderHealthSection(freshHealth);
 972	                    if (fresh) {
 973	                        updateStatusTable(tbody, fresh);
 974	                        updateMissingReposRow(fresh);
 975	                    }
 976	                }
 977	            } catch {
 978	                // Silently ignore polling errors — stale badges remain.
 979	            } finally {
 980	                refreshInProgress = false;
 981	                remainingSeconds = pollIntervalMs / 1000;
 982	                progressBar.classList.remove('refreshing');
 983	                progressBar.style.width = '0%';
 984	            }
 985	        }
 986	
 987	        /**
 988	         * Manual force-refresh — calls the live git-fetch endpoint.
 989	         */
 990	        async function doRefresh() {
 991	            if (refreshInProgress) return;
 992	            refreshInProgress = true;
 993	            refreshNowBtn.disabled = true;
 994	            progressBar.classList.add('refreshing');
 995	            try {
 996	                const [fresh, freshHealth] = await Promise.all([
 997	                    api.status.refresh(projectId, wid),
 998	                    api.workspaces.health(projectId, wid).catch(() => null),
 999	                ]);
1000	                if (container.isConnected) {
1001	                    renderHealthSection(freshHealth);
1002	                    if (fresh) {
1003	                        updateStatusTable(tbody, fresh);
1004	                        updateMissingReposRow(fresh);
1005	                    }
1006	                }
1007	            } catch {
1008	                // Silently ignore — stale badges remain.
1009	            } finally {
1010	                refreshInProgress = false;
1011	                refreshNowBtn.disabled = false;
1012	                remainingSeconds = pollIntervalMs / 1000;
1013	                progressBar.classList.remove('refreshing');
